export type ToolKey =
  | 'waterlow' | 'must' | 'falls' | 'moving_handling' | 'bed_rails'
  | 'eating_drinking' | 'oral_health' | 'peep' | 'abbey_pain'
  // v89
  | 'delirium_4at' | 'mood_gds15' | 'behaviour_support' | 'leaving_building' | 'hydration'
  | 'self_medication' | 'personal_fire' | 'wheelchair_belt' | 'bowel' | 'seizure' | 'catheter' | 'emotional_safety';

export type Level = 'none' | 'low' | 'medium' | 'high' | 'very_high' | 'mild' | 'moderate' | 'severe' | 'not_scored';

export type Answer = string | number | string[] | null | undefined;
export type Answers = Record<string, Answer>;

export interface Option {
  value: string;
  label: string;
  points?: number;
  hint?: string;
  /** For multi-selects: picking this clears the others ("None of these"). */
  exclusive?: boolean;
  /** Shown to carers on the resident when chosen (falls actions, etc.). */
  fact?: string;
}

export interface Question {
  key: string;
  label: string;
  hint?: string;
  type: 'choice' | 'multi' | 'number' | 'text' | 'date';
  options?: Option[];
  unit?: string;
  min?: number;
  max?: number;
  /** Not every question must be answered. Choices and numbers are required unless this is set. */
  optional?: boolean;
  showIf?: (a: Answers) => boolean;
}

export interface Section { key: string; title: string; intro?: string; questions: Question[] }

export interface Context {
  ageYears?: number | null;
  sex?: string | null;
  weightKg?: number | null;
  heightCm?: number | null;
  /** Weight 3–6 months ago, if the record has one. */
  pastWeightKg?: number | null;
  pastWeightDate?: string | null;
  roomNumber?: string | null;
  medicines?: string[];
  /** v89: days since bowels were last recorded as opened, if known. */
  lastBowelOpenedDays?: number | null;
  /** v89: the resident's current DoLS status, if recorded. */
  dolsStatus?: string | null;
}

export interface PlanSuggestion {
  domain: string;
  riskLevel?: 'low' | 'medium' | 'high';
  need?: string;
  outcome?: string;
  interventions: string[];
  equipment?: string[];
  staff?: string;
  /** Merged into the section's structured details (see careDetails.ts). */
  details?: Record<string, unknown>;
  schedule?: { time: string; what: string; dayOfWeek?: number | null }[];
}

export interface Result {
  complete: boolean;
  /** Keys of required questions not yet answered. */
  missing: string[];
  /** Answers that contradict each other or leave something unsafe. Saving is refused. */
  errors: string[];
  /** Safety points the assessor must see. Saving is allowed. */
  warnings: string[];
  score: number | null;
  maxScore?: number;
  level: Level;
  /** One line: "High risk (15–19)". */
  headline: string;
  /** Why: each thing that contributed. */
  reasons: string[];
  /** What to do now. */
  actions: string[];
  reviewDays: number;
  reviewNote: string;
  plan: PlanSuggestion;
  /** Short lines carers see before helping, e.g. "Transfers: full hoist, M sling, 2 carers". */
  facts: string[];
  /** Integer stored in risk_assessments.total_score (a count where the tool has no score). */
  storedScore: number;
}

export interface Tool {
  /** A built-in ToolKey, or "custom:<id>" for the home's own (v90). */
  key: string;
  name: string;
  shortName: string;
  version: string;
  purpose: string;
  /** Who should complete it. */
  who: string;
  domain: string;
  sources: { label: string; url: string }[];
  scored: boolean;
  /** v89: grouping on screens. */
  group?: 'clinical' | 'safety' | 'wellbeing';
  /** v89: set for tools only some people need ("Only for people with a catheter"). Not counted as "never done". */
  whenNeeded?: string;
  sections: Section[];
  evaluate(a: Answers, ctx?: Context): Result;
  /** Suggested answers from what the record already holds. The assessor confirms each one. */
  prefill?(ctx: Context): Answers;
}

// ── helpers ──────────────────────────────────────────────────────────────────

export const YES_NO: Option[] = [{ value: 'yes', label: 'Yes' }, { value: 'no', label: 'No' }];

export function str(a: Answer): string { return a === null || a === undefined ? '' : Array.isArray(a) ? a.join(',') : String(a).trim(); }
export function list(a: Answer): string[] { return Array.isArray(a) ? a.map(String) : a ? [String(a)] : []; }
export function num(a: Answer): number | null {
  if (a === null || a === undefined || a === '' || Array.isArray(a)) return null;
  const n = typeof a === 'number' ? a : Number(a);
  return Number.isFinite(n) ? n : null;
}

export function allQuestions(t: { sections: Section[] }): Question[] { return t.sections.flatMap(s => s.questions); }

/** Required questions not answered, honouring showIf. */
export function missingAnswers(t: { sections: Section[] }, a: Answers): string[] {
  const out: string[] = [];
  for (const q of allQuestions(t)) {
    if (q.showIf && !q.showIf(a)) continue;
    if (q.optional || q.type === 'text' || q.type === 'date') continue;
    const v = a[q.key];
    if (q.type === 'multi') { if (list(v).length === 0) out.push(q.key); continue; }
    if (q.type === 'number') {
      const n = num(v);
      if (n === null || (q.min !== undefined && n < q.min) || (q.max !== undefined && n > q.max)) out.push(q.key);
      continue;
    }
    const s = str(v);
    if (!s || (q.options && !q.options.some(o => o.value === s))) out.push(q.key);
  }
  return out;
}

export function q(t: { sections: Section[] }, key: string): Question | undefined { return allQuestions(t).find(x => x.key === key); }
export function opt(t: { sections: Section[] }, key: string, value: Answer): Option | undefined {
  return q(t, key)?.options?.find(o => o.value === str(value));
}
export function points(t: { sections: Section[] }, key: string, a: Answers): number {
  const qq = q(t, key);
  if (!qq || !qq.options) return 0;
  if (qq.type === 'multi') return list(a[key]).reduce((s, v) => s + (qq.options!.find(o => o.value === v)?.points || 0), 0);
  return opt(t, key, a[key])?.points || 0;
}
export function labelsOf(t: { sections: Section[] }, key: string, a: Answers): string[] {
  const qq = q(t, key);
  if (!qq || !qq.options) return [];
  return list(a[key]).map(v => qq.options!.find(o => o.value === v)).filter((o): o is Option => !!o && !o.exclusive).map(o => o.label);
}
export function uniq<T>(xs: T[]): T[] { return Array.from(new Set(xs)); }

/** "Every 4 hours, 06:00 to 22:00" → schedule items. Kept in this file so it has no imports. */
export function timesEvery(hours: number, from = '06:00', to = '22:00'): string[] {
  const p = (s: string) => { const [h, m] = s.split(':').map(Number); return h * 60 + m; };
  if (!(hours >= 1 && hours <= 12)) return [];
  const a = p(from), b0 = p(to);
  const b = b0 >= a ? b0 : b0 + 1440;
  const out: string[] = [];
  for (let t = a; t <= b && out.length < 24; t += hours * 60) {
    const mm = t % 1440;
    out.push(`${String(Math.floor(mm / 60)).padStart(2, '0')}:${String(mm % 60).padStart(2, '0')}`);
  }
  return out;
}

export function base(t: { sections: Section[] }, a: Answers, domain: string): Result {
  const missing = missingAnswers(t, a);
  return {
    complete: missing.length === 0, missing, errors: [], warnings: [], score: null, level: 'not_scored',
    headline: '', reasons: [], actions: [], reviewDays: 28, reviewNote: '', plan: { domain, interventions: [] },
    facts: [], storedScore: 0,
  };
}

export function bmiOf(weightKg?: number | null, heightCm?: number | null): number | null {
  if (!weightKg || !heightCm || weightKg <= 0 || heightCm < 100 || heightCm > 230) return null;
  const m = heightCm / 100;
  return Math.round((weightKg / (m * m)) * 10) / 10;
}

export function lossPct(now?: number | null, before?: number | null): number | null {
  if (!now || !before || now <= 0 || before <= 0) return null;
  return Math.round(((before - now) / before) * 1000) / 10;
}
